import itertools

def solve():
    # We can't easily simulate all sequences, but we can use BFS for small n.
    # State is a bitmask of the n*n board.
    # n=2: board size 4.
    n = 2
    initial_state = 0
    visited = {initial_state}
    queue = [initial_state]

    # L-tromino: (i,j), (i+1,j), (i,j+1)
    trominoes = []
    for i in range(n-1):
        for j in range(n-1):
            trominoes.append(((i,j), (i+1,j), (i,j+1)))

    # Rows
    rows = []
    for i in range(n):
        rows.append([(i, j) for j in range(n)])

    # Cols
    cols = []
    for j in range(n):
        cols.append([(i, j) for i in range(n)])

    def get_bit(r, c):
        return 1 << (r * n + c)

    # Convert cells to masks
    t_masks = []
    for t in trominoes:
        mask = 0
        for r, c in t:
            mask |= get_bit(r, c)
        t_masks.append(mask)

    r_masks = []
    for r in rows:
        mask = 0
        for row, col in r:
            mask |= get_bit(row, col)
        r_masks.append(mask)

    c_masks = []
    for c in cols:
        mask = 0
        for row, col in c:
            mask |= get_bit(row, col)
        c_masks.append(mask)

    # BFS
    idx = 0
    while idx < len(queue):
        state = queue[idx]
        idx += 1

        # Try placing trominoes
        for tm in t_masks:
            if (state & tm) == 0:
                new_state = state | tm
                if new_state == 0: # Found a way back to empty
                    return True
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)

        # Try clearing rows
        for rm in r_masks:
            if (state & rm) == rm:
                new_state = state & ~rm
                if new_state == 0:
                    # Check if it's a non-zero number of moves
                    # state was not 0, so we just performed at least one move.
                    # Wait, the initial state is 0. 
                    # We need to start from 0, do some moves, and return to 0.
                    # So the first move must be placing a tromino.
                    # After the first move, we are not at 0.
                    # Then we might return to 0.
                    return True
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)

        # Try clearing columns
        for cm in c_masks:
            if (state & cm) == cm:
                new_state = state & ~cm
                if new_state == 0:
                    return True
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)
    return False

