import collections

def solve_with_path(n):
    initial_state = 0
    visited = {initial_state: None}
    queue = collections.deque([initial_state])

    trominoes = []
    for i in range(n-1):
        for j in range(n-1):
            trominoes.append(((i,j), (i+1,j), (i,j+1)))

    rows = [[(i, j) for j in range(n)] for i in range(n)]
    cols = [[(i, j) for i in range(n)] for j in range(n)]

    def get_bit(r, c):
        return 1 << (r * n + c)

    t_masks = []
    for t in trominoes:
        mask = 0
        for r, c in t:
            mask |= get_bit(r, c)
        t_masks.append(mask)

    r_masks = []
    for r in rows:
        mask = 0
        for row, col in r:
            mask |= get_bit(row, col)
        r_masks.append(mask)

    c_masks = []
    for c in cols:
        mask = 0
        for row, col in c:
            mask |= get_bit(row, col)
        c_masks.append(mask)

    while queue:
        state = queue.popleft()

        for tm in t_masks:
            if (state & tm) == 0:
                new_state = state | tm
                if new_state not in visited:
                    visited[new_state] = (state, 'T')
                    queue.append(new_state)

        for rm in r_masks:
            if (state & rm) == rm:
                new_state = state & ~rm
                if new_state == 0:
                    # Path found!
                    path = []
                    curr = state
                    while curr is not None:
                        prev, move = visited[curr]
                        path.append(move)
                        curr = prev
                    return path[::-1] + ['R']
                if new_state not in visited:
                    visited[new_state] = (state, 'R')
                    queue.append(new_state)

        for cm in c_masks:
            if (state & cm) == cm:
                new_state = state & ~cm
                if new_state == 0:
                    # Path found!
                    path = []
                    curr = state
                    while curr is not None:
                        prev, move = visited[curr]
                        path.append(move)
                        curr = prev
                    return path[::-1] + ['C']
                if new_state not in visited:
                    visited[new_state] = (state, 'C')
                    queue.append(new_state)
    return None

